projection.source:
//! Source projection provenance for parsed functions and Default expansions.
//! Module membership is a container relation, never a claim that a module's
//! declaration bytes were authored: the loader also injects library modules.
use crate::{ast as a, names};
use std::collections::{BTreeMap, BTreeSet};

pub(super) struct Origins {
    pub functions: Vec<Option<usize>>,
    pub implementations: Vec<Option<usize>>,
    pub types: BTreeMap<usize, usize>,
    pub expressions: BTreeMap<usize, usize>,
    pub blocks: BTreeMap<usize, usize>,
}
struct Written {
    functions: BTreeSet<usize>,
    implementations: BTreeSet<usize>,
    traits: BTreeSet<usize>,
    structures: BTreeSet<usize>,
}
fn failure(identity: &str, detail: &str) -> String {
    format!("\"{identity}\" E_IDENTITY_ORIGIN {detail}")
}
fn same_span(left: a::Span, right: a::Span) -> bool {
    left.file == right.file && left.start == right.start && left.end == right.end
        && left.line == right.line && left.column == right.column
}
fn remember(program: &a::Program, written: &mut Written, item: a::Item) -> Result<(), String> {
    let valid = match item {
        a::Item::Function(index) => index < program.functions.len() && written.functions.insert(index),
        a::Item::Impl(index) => index < program.impls.len() && written.implementations.insert(index),
        a::Item::Trait(index) => index < program.traits.len() && written.traits.insert(index),
        a::Item::Struct(index) => index < program.structs.len() && written.structures.insert(index),
        _ => true,
    };
    if !valid { return Err(failure("source", "duplicate or out-of-range parsed declaration")); }
    Ok(())
}
fn mark(nodes: &mut BTreeMap<usize, usize>, index: usize, function: usize) -> Result<(), String> {
    if nodes.contains_key(&index) {
        return Err(failure("source", "generated nodes have more than one expansion owner"));
    }
    nodes.insert(index, function); Ok(())
}
fn path_structure(program: &a::Program, path: &a::Path) -> Option<usize> {
    let declaration = program.declarations.get(path.declaration?)?;
    match declaration.item { a::Item::Struct(index) => Some(index), _ => None }
}
fn target_path(program: &a::Program, expression: usize, structure: usize,
    arguments: &[usize], span: a::Span) -> bool {
    let Some(node) = program.exprs.get(expression) else { return false; };
    if !same_span(node.span, span) { return false; }
    match &node.kind {
        a::Expr::Path(path) => path_structure(program, path) == Some(structure) && path.args.as_slice() == arguments,
        _ => false,
    }
}
fn field_value(program: &a::Program, field: &a::Field, value: usize, function: usize,
    origins: &mut Origins) -> Result<(), String> {
    let node = program.exprs.get(value).ok_or_else(|| -> String { failure("source", "generated field value is absent") })?;
    if !same_span(node.span, field.span) { return Err(failure("source", "generated field value has a different defining span")); }
    let a::Expr::Call { callee, args } = &node.kind else {
        return Err(failure("source", "generated field value is not a Default helper call"));
    };
    if !args.is_empty() { return Err(failure("source", "generated field helper has source arguments")); }
    let called = program.exprs.get(*callee).ok_or_else(|| -> String { failure("source", "generated field callee is absent") })?;
    let a::Expr::Path(path) = &called.kind else { return Err(failure("source", "generated field callee is not a path")); };
    if !same_span(called.span, field.span) || path.args.len() != 1usize || path.args[0usize] != field.ty
        || !path.declaration.and_then(|index| program.declarations.get(index))
            .is_some_and(|declaration| matches!(declaration.item, a::Item::Function(_))) {
        return Err(failure("source", "generated field helper does not retain its authored field type"));
    }
    // field.ty is deliberately NOT marked: this node belongs to the written field.
    mark(&mut origins.expressions, *callee, function)?;
    mark(&mut origins.expressions, value, function)
}
fn derived_default(program: &a::Program, written: &Written, implementation: usize,
    origins: &mut Origins) -> Result<usize, String> {
    let value = &program.impls[implementation];
    let label = format!("implementation:{implementation}");
    let target = program.types.get(value.target).ok_or_else(|| -> String { failure(&label, "implementation target is absent") })?;
    let a::Type::Path(target_name) = &target.kind else { return Err(failure(&label, "unwritten implementation has no nominal target")); };
    let structure = path_structure(program, target_name).ok_or_else(|| -> String { failure(&label, "unwritten implementation does not target a resolved struct") })?;
    let definition = program.structs.get(structure).ok_or_else(|| -> String { failure(&label, "generated struct target is absent") })?;
    let identity = names::qualified(&definition.module, &definition.name);
    if !written.structures.contains(&structure) || !same_span(value.span, definition.span)
        || !same_span(target.span, definition.span) || value.module != definition.module {
        return Err(failure(&identity, "unwritten implementation has no matching parsed defining struct"));
    }
    let mut requests = 0usize;
    for attribute in &definition.attrs {
        if attribute.name == "derive" {
            for name in &attribute.args { if name == "Default" { requests += 1usize; } }
        }
    }
    if requests != 1usize || value.methods.len() != 1usize || !value.associated.is_empty()
        || value.generics.len() != definition.generics.len() || target_name.args.len() != definition.generics.len() {
        return Err(failure(&identity, "unwritten implementation is not the recorded Default expansion shape"));
    }
    let function = value.methods[0usize];
    let method = program.functions.get(function).ok_or_else(|| -> String { failure(&identity, "generated Default method is absent") })?;
    if method.name != "default" || method.module != definition.module || !method.params.is_empty()
        || !method.generics.is_empty() || !method.attrs.is_empty() || method.result != value.target
        || method.public != a::Visibility::Public || !same_span(method.span, definition.span) {
        return Err(failure(&identity, "generated Default method does not match its defining struct"));
    }
    let bound = value.trait_ty.ok_or_else(|| -> String { failure(&identity, "generated Default trait is absent") })?;
    let bound_node = program.types.get(bound).ok_or_else(|| -> String { failure(&identity, "generated Default bound type is absent") })?;
    let a::Type::Path(bound_name) = &bound_node.kind else { return Err(failure(&identity, "generated Default bound is not a resolved trait path")); };
    if !same_span(bound_node.span, definition.span) || !bound_name.args.is_empty()
        || !bound_name.declaration.and_then(|index| program.declarations.get(index))
            .is_some_and(|declaration| matches!(declaration.item, a::Item::Trait(_))) {
        return Err(failure(&identity, "generated Default bound is not a resolved trait at the defining span"));
    }
    let expected_target = bound.checked_add(definition.generics.len())
        .and_then(|index| index.checked_add(1usize))
        .ok_or_else(|| -> String { failure(&identity, "generated type indices overflow") })?;
    if value.target != expected_target {
        return Err(failure(&identity, "generated target does not follow its newly allocated type arguments"));
    }
    mark(&mut origins.types, bound, function)?;
    for (index, parameter) in definition.generics.iter().enumerate() {
        let argument = target_name.args[index];
        let expected = bound.checked_add(index).and_then(|index| index.checked_add(1usize))
            .ok_or_else(|| -> String { failure(&identity, "generated argument index overflows") })?;
        let node = program.types.get(argument).ok_or_else(|| -> String { failure(&identity, "generated type argument is absent") })?;
        let a::Type::Path(path) = &node.kind else { return Err(failure(&identity, "generated argument is not a parameter path")); };
        let copied = &value.generics[index];
        if argument != expected || path.name != parameter.name || path.declaration.is_some()
            || !path.args.is_empty() || !same_span(node.span, parameter.span)
            || copied.name != parameter.name || copied.lifetime != parameter.lifetime
            || !same_span(copied.span, parameter.span) {
            return Err(failure(&identity, "generated parameter argument or copied generic differs"));
        }
        let extra = if parameter.lifetime { 0usize } else { 1usize };
        if copied.bounds.len() != parameter.bounds.len() + extra {
            return Err(failure(&identity, "generated generic does not retain its authored bounds"));
        }
        for (at, original) in parameter.bounds.iter().enumerate() {
            if *original >= bound || copied.bounds[at] != *original {
                return Err(failure(&identity, "generated generic reuses a non-authored bound"));
            }
        }
        if extra != 0usize && copied.bounds[parameter.bounds.len()] != bound {
            return Err(failure(&identity, "generated generic is missing its fresh Default bound"));
        }
        // Only this freshly allocated argument is marked, never original bounds.
        mark(&mut origins.types, argument, function)?;
    }
    for field in &definition.fields {
        if field.ty >= bound { return Err(failure(&identity, "generated expansion aliases an authored field type")); }
    }
    mark(&mut origins.types, value.target, function)?;
    let block = method.body.ok_or_else(|| -> String { failure(&identity, "generated Default body is absent") })?;
    let body = program.blocks.get(block).ok_or_else(|| -> String { failure(&identity, "generated Default block is absent") })?;
    if !same_span(body.span, definition.span) || !body.statements.is_empty() {
        return Err(failure(&identity, "generated Default block is not its defining expansion"));
    }
    let tail = body.tail.ok_or_else(|| -> String { failure(&identity, "generated Default body has no result") })?;
    let node = program.exprs.get(tail).ok_or_else(|| -> String { failure(&identity, "generated Default result is absent") })?;
    if !same_span(node.span, definition.span) { return Err(failure(&identity, "generated result has a different defining span")); }
    if definition.unit {
        if !target_path(program, tail, structure, &target_name.args, definition.span) {
            return Err(failure(&identity, "generated unit constructor differs from its defining struct"));
        }
    } else if definition.tuple {
        let a::Expr::Call { callee, args } = &node.kind else { return Err(failure(&identity, "generated tuple constructor is not a call")); };
        if !target_path(program, *callee, structure, &target_name.args, definition.span)
            || args.len() != definition.fields.len() {
            return Err(failure(&identity, "generated tuple constructor differs from its defining struct"));
        }
        mark(&mut origins.expressions, *callee, function)?;
        for (index, field) in definition.fields.iter().enumerate() {
            field_value(program, field, args[index], function, origins)?;
        }
    } else {
        let a::Expr::Struct { path, fields, base } = &node.kind else { return Err(failure(&identity, "generated named constructor is not a record")); };
        if path_structure(program, path) != Some(structure) || path.args != target_name.args
            || base.is_some() || fields.len() != definition.fields.len() {
            return Err(failure(&identity, "generated named constructor differs from its defining struct"));
        }
        for (index, field) in definition.fields.iter().enumerate() {
            if fields[index].0 != field.name { return Err(failure(&identity, "generated field order differs")); }
            field_value(program, field, fields[index].1, function, origins)?;
        }
    }
    mark(&mut origins.expressions, tail, function)?;
    mark(&mut origins.blocks, block, function)?;
    origins.functions[function] = Some(structure);
    Ok(structure)
}
pub(super) fn collect(program: &a::Program) -> Result<Origins, String> {
    if !program.resolved || program.function_owners.len() != program.functions.len() {
        return Err(failure("source", "generated origin requires a complete resolved ownership relation"));
    }
    let mut written = Written { functions: BTreeSet::new(), implementations: BTreeSet::new(),
        traits: BTreeSet::new(), structures: BTreeSet::new() };
    for item in &program.items { remember(program, &mut written, *item)?; }
    for module in &program.modules {
        for item in &module.items { remember(program, &mut written, *item)?; }
    }
    for block in &program.blocks {
        for statement in &block.statements {
            if let a::Stmt::Item(item) = statement { remember(program, &mut written, *item)?; }
        }
    }
    let mut result = Origins { functions: vec![None; program.functions.len()],
        implementations: vec![None; program.impls.len()], types: BTreeMap::new(),
        expressions: BTreeMap::new(), blocks: BTreeMap::new() };
    for index in 0usize..program.impls.len() {
        if !written.implementations.contains(&index) {
            let owner = derived_default(program, &written, index, &mut result)?;
            result.implementations[index] = Some(owner);
        }
    }
    for (index, function) in program.functions.iter().enumerate() {
        let authored = match program.function_owner(a::FunctionId { index }) {
            a::FunctionOwner::Free => written.functions.contains(&index),
            a::FunctionOwner::Trait(owner) => !written.functions.contains(&index) && written.traits.contains(&owner.index),
            a::FunctionOwner::Implementation(owner) => {
                if owner.index >= result.implementations.len() {
                    return Err(failure(&function.name, "function implementation owner is absent"));
                }
                if let Some(structure) = result.implementations[owner.index] {
                    if written.functions.contains(&index) || result.functions[index] != Some(structure) {
                        return Err(failure(&function.name, "generated function does not belong to its validated expansion"));
                    }
                    continue;
                }
                !written.functions.contains(&index) && written.implementations.contains(&owner.index)
            }
        };
        if !authored {
            return Err(failure(&names::qualified(&function.module, &function.name), "function has no parsed declaration or validated expansion"));
        }
    }
    Ok(result)
}

operations.source:
fn append(
    result: &mut Catalog, files: &[SourceText], identity: String, parent: String,
    kind: &str, name: &str, span: a::Span, body: Option<(usize, usize)>,
    ty: String, attributes: bool,
) -> Result<(), String> {
    if result.by_identity.contains_key(&identity) {
        return Err(format!("E_IDENTITY duplicate source identity {}", quote(&identity)));
    }
    let file = &files[span.file];
    if span.start > span.end || span.end > file.text.len() {
        return Err(format!("E_IDENTITY invalid source span for {}", quote(&identity)));
    }
    let start = if attributes { preceding(&file.tokens, span.start) } else { span.start };
    let mut signature_end = match body { Some((begin, _)) => begin, None => span.end };
    if matches!(kind, "module" | "trait" | "implementation") {
        let mut at = token_at(&file.tokens, span.start);
        while at < file.tokens.len() && file.tokens[at].span.start < span.end {
            if file.tokens[at].text == "{" { signature_end = file.tokens[at].span.start; break; }
            at += 1usize;
        }
    }
    let (name_start, name_end) = name_span(file, span.start, signature_end, name);
    // String slicing validates its entire backing file through as_str().
    // Validate only the selected ranges; source/token spans remain checked.
    let text = String::from_utf8(file.text.as_bytes()[start..span.end].to_vec())
        .map_err(|_| -> String { "E_IDENTITY item span splits UTF-8".to_string() })?;
    let signature = String::from_utf8(file.text.as_bytes()[start..signature_end].to_vec())
        .map_err(|_| -> String { "E_IDENTITY signature span splits UTF-8".to_string() })?;
    let body_digest = match body {
        Some((begin, end)) => token_digest(&file.tokens, begin, end),
        None => String::new(),
    };
    let generated_from = match result.by_identity.get(&parent) {
        Some(index) => result.items[*index].generated_from.clone(), None => String::new(),
    };
    let generated = !generated_from.is_empty();
    let signature = if generated { ty.clone() } else { signature };
    let text = if generated { String::new() } else { text };
    let signature_digest = if generated { normalized_digest(&signature)? }
        else { token_digest(&file.tokens, start, signature_end) };
    let item = Item {
        identity: identity.clone(), parent, kind: kind.to_string(), name: name.to_string(),
        file: file.path.clone(), start, end: span.end,
        name_start: if generated { start } else { name_start },
        name_end: if generated { start } else { name_end },
        body: if generated { None } else { body }, generated_from, signature_digest,
        text_digest: sha256::hex_digest(text.as_bytes()), body_digest,
        signature, text, type_name: ty, type_resolved: !matches!(kind, "binding" | "call-site"), file_digest: file.digest.clone(),
        references_complete: !generated,
    };
    result.by_identity.insert(identity, result.items.len());
    result.items.push(item);
    Ok(())
}

fn catalog_mode(program: &a::Program, inputs: &[(String, Vec<u8>)], checked: &ir::CheckedProgram,
    evidence: &Option<crate::elaborate::semantic::Evidence>, include_references: bool) -> Result<Catalog, String> {
    if !program.resolved { return Err("E_IDENTITY source is not resolved".to_string()); }
    let origins = origins::collect(program)?;
    let mut by_path: BTreeMap<String, usize> = BTreeMap::new();
    let mut input_identity = b"lkjscript-source-snapshot-1"[..].to_vec();
    for (index, (path, raw)) in inputs.iter().enumerate() { by_path.insert(path.clone(), index); }
    for (path, index) in &by_path {
        bytes(&mut input_identity, path.as_bytes());
        bytes(&mut input_identity, sha256::hex_digest(&inputs[*index].1).as_bytes());
    }
    let mut files = Vec::new();
    for file in &program.files {
        let index = by_path.get(&file.path).ok_or_else(|| -> String { format!("E_IDENTITY missing source {}", quote(&file.path)) })?;
        let raw = &inputs[*index].1;
        let text = String::from_utf8(raw.clone()).map_err(|_| -> String { "E_IDENTITY source is not UTF-8".to_string() })?;
        let tokens = syntax::semantic_tokens(&text).map_err(|problem| problem.message)?;
        files.push(SourceText { path: file.path.clone(), digest: sha256::hex_digest(raw), text, tokens });
    }
    let mut result = Catalog {
        root: program.files[0usize].path.clone(), module_sources: Vec::new(), references_recorded: include_references,
        items: Vec::new(), by_identity: BTreeMap::new(), references: Vec::new(), generated_references: Vec::new(), unresolved: Vec::new(),
        expression_types: BTreeMap::new(),
        function_ids: Vec::new(), instance_ids: Vec::new(), instance_sources: Vec::new(),
        implementations: Vec::new(), instance_arguments: Vec::new(), input_digest: sha256::hex_digest(&input_identity),
    };
    let mut mounted: BTreeSet<String> = BTreeSet::new();
    for loaded in &program.loaded_modules {
        if loaded.scope >= program.scopes.len() || loaded.file >= program.files.len() {
            return Err("E_IDENTITY invalid loaded module source".to_string());
        }
        let scope = &program.scopes[loaded.scope];
        let identity = root_parent(&scope.path);
        if !mounted.insert(identity.clone()) {
            return Err(format!("E_IDENTITY duplicate loaded module {}", quote(&identity)));
        }
        let parent = match scope.parent {
            Some(parent) => root_parent(&program.scopes[parent].path),
            None => String::new(),
        };
        result.module_sources.push(ModuleSource { identity, parent,
            file: program.files[loaded.file].path.clone(), alternate: loaded.alternate.clone() });
    }
    for index in 0usize..program.functions.len() { result.function_ids.push(function_identity(program, index)); }
    for (index, value) in program.functions.iter().enumerate() {
        let identity = result.function_ids[index].clone();
        let parent = match program.function_owner(a::FunctionId { index }) {
            a::FunctionOwner::Free => root_parent(&value.module),
            a::FunctionOwner::Implementation(owner) => implementation_identity(program, owner.index),
            a::FunctionOwner::Trait(owner) => qualified(&program.traits[owner.index].module, &program.traits[owner.index].name),
        };
        let body = value.body.map(|body| (program.blocks[body].span.start, program.blocks[body].span.end));
        append(&mut result, &files, identity.clone(), parent, "function", &value.name,
            value.span, body, function_signature(program, value), true)?;
        if let Some(structure) = origins.functions[index] {
            generated_projection(&mut result, &files, program, &identity, structure, function_signature(program, value), true)?;
        }
        for (position, parameter) in value.params.iter().enumerate() {
            append(&mut result, &files, parameter_identity(&identity, &parameter.name, position), identity.clone(),
                "parameter", &parameter.name, parameter.span, None, type_name(program, parameter.ty), false)?;
        }
        for parameter in &value.generics {
            append(&mut result, &files, format!("{}::generic:{}", identity, parameter.name), identity.clone(),
                "generic-parameter", &parameter.name, parameter.span, None, parameter.name.clone(), false)?;
        }
    }
    for value in &program.structs {
        let identity = qualified(&value.module, &value.name);
        append(&mut result, &files, identity.clone(), root_parent(&value.module), "struct",
            &value.name, value.span, None, identity.clone(), true)?;
        append_generics(&mut result, &files, &identity, &value.generics)?;
        for field in &value.fields {
            append(&mut result, &files, format!("{}::field:{}", identity, field.name), identity.clone(), "field",
                &field.name, field.span, None, type_name(program, field.ty), false)?;
        }
    }
    for value in &program.enums {
        let identity = qualified(&value.module, &value.name);
        append(&mut result, &files, identity.clone(), root_parent(&value.module), "enum",
            &value.name, value.span, None, identity.clone(), true)?;
        append_generics(&mut result, &files, &identity, &value.generics)?;
        for variant in &value.variants {
            let variant_identity = format!("{}::variant:{}", identity, variant.name);
            append(&mut result, &files, variant_identity.clone(), identity.clone(), "variant",
                &variant.name, variant.span, None, identity.clone(), false)?;
            for field in &variant.fields {
                append(&mut result, &files, format!("{}::field:{}", variant_identity, field.name), variant_identity.clone(),
                    "field", &field.name, field.span, None, type_name(program, field.ty), false)?;
            }
        }
    }
    for value in &program.traits {
        let identity = qualified(&value.module, &value.name);
        append(&mut result, &files, identity.clone(), root_parent(&value.module), "trait", &value.name,
            value.span, None, identity.clone(), true)?;
        append_generics(&mut result, &files, &identity, &value.generics)?;
        for associated in &value.associated {
            append(&mut result, &files, format!("{}::type:{}", identity, associated.name), identity.clone(),
                "associated-type", &associated.name, associated.span, None,
                associated.value.map_or("_".to_string(), |ty| type_name(program, ty)), false)?;
        }
    }
    for (index, value) in program.impls.iter().enumerate() {
        let identity = implementation_identity(program, index);
        append(&mut result, &files, identity.clone(), root_parent(&value.module), "implementation", "impl",
            value.span, None, type_name(program, value.target), true)?;
        if let Some(structure) = origins.implementations[index] {
            let signature = format!("impl {} for {}", type_name(program, value.trait_ty.unwrap()), type_name(program, value.target));
            generated_projection(&mut result, &files, program, &identity, structure, signature, false)?;
        }
        append_generics(&mut result, &files, &identity, &value.generics)?;
        result.implementations.push((identity.clone(), type_name(program, value.target),
            value.trait_ty.map_or(String::new(), |ty| type_name(program, ty))));
        for associated in &value.associated {
            append(&mut result, &files, format!("{}::type:{}", identity, associated.name), identity.clone(),
                "associated-type", &associated.name, associated.span, None,
                associated.value.map_or("_".to_string(), |ty| type_name(program, ty)), false)?;
        }
    }
    for value in &program.modules {
        let identity = qualified(&value.parent, &value.name);
        append(&mut result, &files, identity.clone(), root_parent(&value.parent), "module", &value.name,
            value.span, None, identity, true)?;
    }
    for value in &program.aliases {
        append(&mut result, &files, qualified(&value.module, &value.name), root_parent(&value.module), "alias",
            &value.name, value.span, None, type_name(program, value.ty), true)?;
        append_generics(&mut result, &files, &qualified(&value.module, &value.name), &value.generics)?;
    }
    for value in &program.constants {
        append(&mut result, &files, qualified(&value.module, &value.name), root_parent(&value.module), "constant",
            &value.name, value.span, None, type_name(program, value.ty), true)?;
    }
    if include_references {
        let owners = Owners::new(&result);
        let resolver = resolve::Resolver::new(program).map_err(|problem| problem.message)?;
        import_qualifications(&mut result, &files, program, &resolver);
        visibility_qualifications(&mut result, &files, &owners);
        // Every declaration-backed type path is a resolved reference, including aliases.
        for (type_index, node) in program.types.iter().enumerate() {
            if let Some(function) = origins.types.get(&type_index) {
                let owner = result.function_ids[*function].clone();
                let target = match &node.kind {
                    a::Type::Path(path) => {
                        path.declaration.and_then(|declaration| declaration_identity(program, declaration, &result.function_ids))
                            .or_else(|| {
                                let structure = origins.functions[*function]?;
                                let definition = &program.structs[structure];
                                let candidate = format!("{}::generic:{}", qualified(&definition.module, &definition.name), path.name);
                                if result.by_identity.contains_key(&candidate) { Some(candidate) } else { None }
                            })
                    }
                    _ => None,
                };
                generated_reference(&mut result, &files, &owner, target, node.span, "type");
                continue;
            }
            if let a::Type::Path(path) = &node.kind {
                let file = &files[node.span.file];
                let Some(owner) = owners.get(&file.path, node.span.start, node.span.end) else { continue; };
                path_qualifications(&mut result, &files, program, &resolver, &owner, node.scope, node.span);
                if let Some(declaration) = path.declaration {
                    if let Some(target) = declaration_identity(program, declaration, &result.function_ids) {
                        if module_name(&path.name) == target {
                            path_reference(&mut result, &files, owner, target, node.span, "type", &resolver, node.scope, true);
                        } else {
                            add_reference(&mut result, &files, owner, path.name.clone(), node.span,
                                leaf_name(&path.name), "associated-type", false);
                        }
                    }
                }
            }
        }
        for imported in &program.uses {
            if imported.glob { continue; }
            let scope = resolve::module(program, &imported.module);
            let path = a::Path { declaration: None, name: imported.path.clone(), args: Vec::new() };
            let mut target: Option<String> = None;
            let mut alias = false;
            if let Ok(resolved) = resolver.value_path(scope, &path, imported.span) {
                target = value_identity(program, &resolved, &result.function_ids);
                alias = resolve::semantic_path_alias(&resolver, scope, &imported.path, true, imported.span).map_err(|problem| problem.message)?;
            }
            if target.is_none() {
                if let Ok(name) = resolver.type_name(scope, &imported.path, imported.span) {
                    let identity = module_name(&name);
                    if result.by_identity.contains_key(&identity) {
                        target = Some(identity);
                        alias = resolve::semantic_path_alias(&resolver, scope, &imported.path, false, imported.span).map_err(|problem| problem.message)?;
                    }
                }
            }
            if let Some(target) = target {
                let owner = root_parent(&imported.module);
                import_reference(&mut result, &files, owner, target, imported, alias);
            }
        }
        pattern_references(&mut result, &files, program, &owners, &resolver);
        let mut local_names: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
        let mut source_functions: BTreeMap<String, usize> = BTreeMap::new();
        for (index, function) in program.functions.iter().enumerate() {
            let mut locals = BTreeSet::new();
            for parameter in &function.params { locals.insert(parameter.name.clone()); }
            local_names.insert(result.function_ids[index].clone(), locals);
            source_functions.insert(result.function_ids[index].clone(), index);
        }
        let mut binding_counts: BTreeMap<(String, String), usize> = BTreeMap::new();
        let mut binding_ids: BTreeMap<usize, String> = BTreeMap::new();
        for (pattern, node) in program.patterns.iter().enumerate() {
            if let a::Pattern::Bind { name, .. } = &node.kind {
                let file = &files[node.span.file];
                if let Some(owner) = owners.get(&file.path, node.span.start, node.span.end) {
                    if let Some(locals) = local_names.get_mut(&owner) { locals.insert(name.clone()); }
                    let key = (owner.clone(), name.clone());
                    let ordinal = binding_counts.get(&key).copied().unwrap_or(0usize);
                    binding_counts.insert(key, ordinal + 1usize);
                    let digest = match result.by_identity.get(&owner) { Some(index) => result.items[*index].body_digest.clone(), None => String::new() };
                    let identity = format!("{}::body:{}::binding:{}:{}", owner, digest, name, ordinal);
                    if !result.by_identity.contains_key(&identity) {
                        binding_ids.insert(pattern, identity.clone());
                        append(&mut result, &files, identity.clone(), owner, "binding", name, node.span, None,
                            "inferred type is unavailable".to_string(), false)?;
                        if let Some(ty) = evidence.as_ref().and_then(|evidence| evidence.bindings.get(&pattern)) {
                            let index = *result.by_identity.get(&identity).unwrap();
                            result.items[index].type_name = ty.clone(); result.items[index].type_resolved = true;
                        }
                    }
                }
            }
        }
        let mut calls: BTreeMap<String, usize> = BTreeMap::new();
        for (expression, node) in program.exprs.iter().enumerate() {
            if let Some(function) = origins.expressions.get(&expression) {
                generated_expression(&mut result, &files, program, expression, *function, &mut calls, evidence)?;
                continue;
            }
            let file = &files[node.span.file];
            let Some(owner) = owners.get(&file.path, node.span.start, node.span.end) else { continue; };
            let key = (file.path.clone(), node.span.start, node.span.end);
            let self_record = matches!(&node.kind, a::Expr::Struct { path, .. } if path.name == "Self");
            let self_claim = if self_record {
                source_functions.get(&owner).and_then(|function| self_constructor(
                    &mut result, &files, program, *function, &owner, node))
            } else { None };
            let ty = evidence.as_ref().and_then(|evidence| evidence.expressions.get(&expression)).cloned()
                .or_else(|| self_claim.as_ref().map(|claim| claim.1.clone()));
            if result.expression_types.contains_key(&key) {
                let previous = result.expression_types.get_mut(&key).unwrap();
                let agrees = match (&*previous, &ty) {
                    (Some(left), Some(right)) => left == right,
                    _ => false,
                };
                if !agrees { *previous = None; }
            } else { result.expression_types.insert(key, ty); }
            match &node.kind {
                a::Expr::Path(path) | a::Expr::Struct { path, .. } => {
                    path_qualifications(&mut result, &files, program, &resolver, &owner, node.scope, node.span);
                    let typed_owner = evidence.as_ref().is_some_and(|evidence| source_functions.get(&owner).is_some_and(|function| evidence.definitions.contains(function)));
                    let mut local_target = evidence.as_ref().and_then(|evidence| evidence.locals.get(&expression)).copied();
                    if local_target.is_none() && !typed_owner && matches!(node.kind, a::Expr::Path(_)) {
                        if let Some(function) = source_functions.get(&owner) {
                            local_target = untyped_local(program, &binding_counts, *function, &owner, &path.name, node.span);
                        }
                    }
                    if let Some(target) = local_target {
                        local_reference(&mut result, &files, program, &binding_ids, &source_functions, &owner, node, &path.name, target);
                        continue;
                    }
                    let local = !typed_owner && local_names.get(&owner).is_some_and(|locals| locals.contains(&path.name));
                    if local {
                        add_reference(&mut result, &files, owner, path.name.clone(), node.span, leaf_name(&path.name), "lexical-name", false);
                        continue;
                    }
                    let closed = source_functions.get(&owner).is_some_and(|function|
                        crate::elaborate::semantic::closed_source_owner(program, *function));
                    if matches!(node.kind, a::Expr::Path(_))
                        && evidence.as_ref().is_some_and(|evidence|
                            typed_associated(&mut result, &files, program, evidence, expression, &owner, closed)) {
                        continue;
                    }
                    let resolved = resolver.value_path(node.scope, path, node.span).ok();
                    let target = if self_record { self_claim.as_ref().map(|claim| claim.0.clone()) }
                        else { resolved.as_ref().and_then(|path| value_identity(program, path, &result.function_ids)) };
                    if self_record {
                        if target.is_none() {
                            record_site(&mut result, &files, owner.clone(), "Self".to_string(),
                                a::Span { end: node.span.start, ..node.span }, "constructor", false);
                        }
                    } else if let Some(target) = &target {
                        path_reference(&mut result, &files, owner.clone(), target.clone(), node.span,
                            if matches!(node.kind, a::Expr::Struct { .. }) { "constructor" } else { "value" },
                            &resolver, node.scope, matches!(node.kind, a::Expr::Struct { .. }));
                    } else if resolved.as_ref().is_some_and(|path| path.declaration.is_some())
                        || (matches!(node.kind, a::Expr::Path(_)) && path.name.contains("::")
                            && resolver.generic_path(path, node.span)) {
                        add_reference(&mut result, &files, owner.clone(), path.name.clone(), node.span, leaf_name(&path.name), "associated-function", false);
                    }
                    constructor_fields(&mut result, &files, program, &owner, node, &target);
                }
                a::Expr::Method { receiver, name, .. } => {
                    let resolved = evidence.as_ref().is_some_and(|evidence| typed_member(&mut result, &files, program, evidence, expression, &owner));
                    if !resolved {
                        let span = a::Span { start: program.exprs[*receiver].span.end, ..node.span };
                        add_reference(&mut result, &files, owner.clone(), name.clone(), span, name, "typed-method", false);
                    }
                }
                a::Expr::Field { value, name } => {
                    let resolved = evidence.as_ref().is_some_and(|evidence| typed_member(&mut result, &files, program, evidence, expression, &owner));
                    if !resolved {
                        let span = a::Span { start: program.exprs[*value].span.end, ..node.span };
                        add_reference(&mut result, &files, owner.clone(), name.clone(), span, name, "typed-field", false);
                    }
                }
                _ => {}
            }
            if matches!(node.kind, a::Expr::Call { .. } | a::Expr::Method { .. }) {
                let ordinal = calls.get(&owner).copied().unwrap_or(0usize);
                calls.insert(owner.clone(), ordinal + 1usize);
                let digest = match result.by_identity.get(&owner) { Some(index) => result.items[*index].body_digest.clone(), None => String::new() };
                let identity = format!("{}::body:{}::call:{}", owner, digest, ordinal);
                append(&mut result, &files, identity.clone(), owner, "call-site", "", node.span, None,
                    "inferred result type is unavailable".to_string(), false)?;
                if let Some(ty) = evidence.as_ref().and_then(|evidence| evidence.expressions.get(&expression)) {
                    let index = *result.by_identity.get(&identity).unwrap();
                    result.items[index].type_name = ty.clone(); result.items[index].type_resolved = true;
                }
            }
        }
    } else {
        // Absence of rows in this mode is never evidence of absence of uses.
        for index in 0usize..result.items.len() { result.items[index].references_complete = false; }
    }
    for function in &checked.program().functions {
        let (source, raw) = match ir_source(program, &result, &function.name) {
            Some(value) => value,
            None => (String::new(), String::new()),
        };
        let arguments = instance_arguments(checked.program(), &raw);
        let identity = if source.is_empty() { format!("ir:{}", module_name(&function.name)) }
            else { format!("ir:{}{}", source, arguments) };
        result.instance_ids.push(identity);
        result.instance_sources.push(source);
        result.instance_arguments.push(arguments);
    }
    let mut ordered: BTreeMap<(String, String, usize, usize, String), Reference> = BTreeMap::new();
    let references = std::mem::replace(&mut result.references, Vec::new());
    for reference in references {
        ordered.insert((reference.owner.clone(), reference.file.clone(), reference.start, reference.end, reference.target.clone()), reference);
    }
    for (_, reference) in ordered { result.references.push(reference); }
    Ok(result)
}

{
        let mut order: BTreeMap<String, Vec<(usize, usize, String)>> = BTreeMap::new();
        for item in &catalog.items {
            if matches!(item.kind.as_str(), "parameter" | "field" | "variant" | "generic-parameter" | "associated-type")
                || item.start == item.end || !item.generated_from.is_empty() { continue; }
            if !order.contains_key(&item.file) { order.insert(item.file.clone(), Vec::new()); }
            order.get_mut(&item.file).unwrap().push((item.start, (!0usize) - item.end, item.identity.clone()));
        }
        let mut files = BTreeMap::new();
        for (file, mut intervals) in order {
            intervals.sort();
            let mut nodes: Vec<Owner> = Vec::new();
            let mut stack: Vec<usize> = Vec::new();
            for (start, inverse_end, identity) in intervals {
                let end = (!0usize) - inverse_end;
                loop {
                    let Some(last) = ({ stack.last().copied() }) else { break; };
                    if nodes[last].start <= start && end <= nodes[last].end { break; }
                    stack.pop();
                }
                let parent = stack.last().copied();
                stack.push(nodes.len());
                nodes.push(Owner { start, end, identity, parent });
            }
            files.insert(file, nodes);
        }
        Self { files }
    }

fn generated_projection(catalog: &mut Catalog, files: &[SourceText], program: &a::Program,
    identity: &str, structure: usize, signature: String, body: bool) -> Result<(), String> {
    let definition = &program.structs[structure];
    let defining = qualified(&definition.module, &definition.name);
    let file = &files[definition.span.file];
    let start = preceding(&file.tokens, definition.span.start);
    let declaration = token_digest(&file.tokens, start, definition.span.end);
    let mut epoch = b"lkjscript-derived-default-body-1"[..].to_vec();
    bytes(&mut epoch, defining.as_bytes()); bytes(&mut epoch, declaration.as_bytes());
    let index = *catalog.by_identity.get(&identity.to_string())
        .ok_or_else(|| -> String { format!("{} E_IDENTITY_ORIGIN generated item is absent", quote(identity)) })?;
    let item = &mut catalog.items[index];
    item.generated_from = defining;
    item.signature_digest = normalized_digest(&signature)?;
    item.signature = signature;
    item.text.clear(); item.text_digest = sha256::hex_digest(b"");
    item.name_start = item.start; item.name_end = item.start;
    item.body = None;
    item.body_digest = if body { sha256::hex_digest(&epoch) } else { String::new() };
    item.references_complete = false;
    Ok(())
}

fn generated_reference(catalog: &mut Catalog, files: &[SourceText], owner: &str,
    target: Option<String>, span: a::Span, kind: &str) {
    catalog.generated_references.push(Reference { owner: owner.to_string(),
        target: target.unwrap_or_else(|| -> String { String::new() }), file: files[span.file].path.clone(),
        kind: kind.to_string(), start: span.start, end: span.end });
}

fn generated_expression(catalog: &mut Catalog, files: &[SourceText], program: &a::Program,
    expression: usize, function: usize, calls: &mut BTreeMap<String, usize>,
    evidence: &Option<crate::elaborate::semantic::Evidence>) -> Result<(), String> {
    let node = &program.exprs[expression];
    let owner = catalog.function_ids[function].clone();
    match &node.kind {
        a::Expr::Path(path) => {
            let target = value_identity(program, path, &catalog.function_ids);
            generated_reference(catalog, files, &owner, target, node.span, "value");
        }
        a::Expr::Struct { path, fields, .. } => {
            let target = value_identity(program, path, &catalog.function_ids);
            generated_reference(catalog, files, &owner, target.clone(), node.span, "constructor");
            for (name, _) in fields {
                let field = target.as_ref().map(|target: &String| -> String { format!("{target}::field:{name}") });
                generated_reference(catalog, files, &owner, field, node.span, "constructor-field");
            }
        }
        a::Expr::Call { callee, .. } => {
            let target = match &program.exprs[*callee].kind {
                a::Expr::Path(path) => value_identity(program, path, &catalog.function_ids),
                _ => None,
            };
            generated_reference(catalog, files, &owner, target, node.span, "call");
            let ordinal = calls.get(&owner).copied().unwrap_or(0usize);
            calls.insert(owner.clone(), ordinal + 1usize);
            let index = *catalog.by_identity.get(&owner).unwrap();
            let epoch = catalog.items[index].body_digest.clone();
            let identity = format!("{owner}::derived:{epoch}::call:{ordinal}");
            let ty = evidence.as_ref().and_then(|value| value.expressions.get(&expression)).cloned();
            append(catalog, files, identity.clone(), owner, "call-site", "", node.span, None,
                ty.clone().unwrap_or_else(|| -> String { "inferred result type is unavailable".to_string() }), false)?;
            let index = *catalog.by_identity.get(&identity).unwrap();
            catalog.items[index].type_resolved = ty.is_some();
        }
        _ => return Err(format!("{} E_IDENTITY_ORIGIN generated expression has no validated form", quote(&owner))),
    }
    Ok(())
}

fn source_signature(item: &semantic::Item) -> Vec<String> {
    let signature = std::str::trim_ascii(item.signature.as_str());
    let parts = chunks(signature);
    let total = parts.len();
    let mut result = Vec::new();
    for (index, part) in parts.iter().enumerate() {
        // Preserve single-chunk spelling; sort longer signatures by fixed-width index.
        let detail = if total == 1usize {
            format!("kind={} text={} bytes={} complete=true", item.kind, semantic::quote(part), signature.len())
        } else {
            format!("kind={} chunk={index:016x} chunks={total} text={} bytes={} complete={}",
                item.kind, semantic::quote(part), signature.len(), index + 1usize == total)
        };
        let detail = if item.generated_from.is_empty() { detail } else {
            format!("{detail} origin=generated definition={} expansion=derive-default source-projection=false", semantic::quote(&item.generated_from))
        };
        result.push(fact(&item.identity, "source-claim", "signature", &detail));
    }
    result
}

pub fn build_emitted(catalog: &semantic::Catalog, checked: &ir::CheckedProgram, native_sizes: &BTreeMap<String, usize>) -> Result<Facts, String> {
    let mut result = Facts::new();
    result.add("meta", "crate", fact("crate", "source-claim", "snapshot",
        &format!("source={} items={} unresolved={} freshness=not-asserted", catalog.input_digest, catalog.items.len(), catalog.unresolved.len())));
    result.empty("outline", "crate"); result.empty("@outline", "crate");
    for item in &catalog.items {
        let origin = if item.generated_from.is_empty() { String::new() } else {
            format!(" origin=generated definition={} source-projection=false span=definition-anchor", semantic::quote(&item.generated_from))
        };
        result.add("meta", &item.identity, fact(&item.identity, "source-claim", "item",
            &format!("kind={} parent={} file={} start={} end={} file-sha256={} item-sha256={} references-complete={}{}",
                item.kind, semantic::quote(&item.parent), semantic::quote(&item.file), item.start, item.end,
                item.file_digest, item.text_digest, item.references_complete, origin)));
        if item.generated_from.is_empty() {
            result.add("meta", &item.identity, fact(&item.identity, "source-claim", "identity",
                &format!("signature={} body={} scope=semantic-path body-locals=token-body-epoch",
                    item.signature_digest, item.body_digest)));
        } else {
            result.add("meta", &item.identity, fact(&item.identity, "source-claim", "origin",
                &format!("origin=generated definition={} expansion=derive-default source-projection=false span=definition-anchor",
                    semantic::quote(&item.generated_from))));
            result.add("meta", &item.identity, fact(&item.identity, "source-claim", "identity",
                &format!("signature={} derived-epoch={} scope=semantic-path body-locals=derived-declaration-epoch epoch-domain=lkjscript-derived-default-body-1",
                    item.signature_digest, item.body_digest)));
        }
        for signature in source_signature(item) {
            result.add("signature", &item.identity, signature.clone());
            result.add("outline", &item.parent, signature);
        }
        result.add("@outline", &item.parent, item.identity.clone());
        if item.generated_from.is_empty() {
            for (index, chunk) in chunks(&item.text).iter().enumerate() {
                result.add("text", &item.identity, fact(&item.identity, "source-claim", "text",
                    &format!("chunk={index:016x} value={}", semantic::quote(chunk))));
            }
        } else {
            result.add("text", &item.identity, fact(&item.identity, "source-claim", "text-unavailable",
                &format!("reason=generated-definition definition={} expansion=derive-default source-projection=false",
                    semantic::quote(&item.generated_from))));
        }
        let type_fact = if matches!(item.kind.as_str(), "binding" | "call-site") { if item.type_resolved { "inferred-type" } else { "type-unavailable" } }
            else if matches!(item.kind.as_str(), "module" | "trait" | "implementation") { "source-kind" } else { "declared-type" };
        result.add("type", &item.identity, fact(&item.identity, "source-claim", type_fact,
            &format!("value={}", semantic::quote(&item.type_name))));

    }
    for (identity, target, trait_name) in &catalog.implementations {
        for which in 0usize..2usize {
            let name = if which == 0usize { target } else { trait_name };
            if name.is_empty() { continue; }
            edge(&mut result, "impls", name, identity, "source-claim", &format!("target={} trait={}", semantic::quote(target), semantic::quote(trait_name)));
            if let Some(at) = name.find('<') {
                edge(&mut result, "impls", &name[..at], identity, "source-claim", &format!("target={} trait={}", semantic::quote(target), semantic::quote(trait_name)));
            }
        }
    }
    for reference in &catalog.references {
        edge(&mut result, "references", &reference.owner, &reference.target, "source-claim",
            &format!("from={} file={} start={} end={} kind={}", semantic::quote(&reference.owner),
                semantic::quote(&reference.file), reference.start, reference.end, reference.kind));
        edge(&mut result, "uses", &reference.target, &reference.owner, "source-claim",
            &format!("target={} file={} start={} end={} kind={}", semantic::quote(&reference.target),
                semantic::quote(&reference.file), reference.start, reference.end, reference.kind));
        edge(&mut result, "dependents", &reference.target, &reference.owner, "source-claim", "change=signature conservative=true");
    }
    for reference in &catalog.generated_references {
        let index = catalog.by_identity.get(&reference.owner)
            .ok_or_else(|| -> String { format!("{} E_IDENTITY_ORIGIN generated reference owner is absent", semantic::quote(&reference.owner)) })?;
        let owner = &catalog.items[*index];
        let detail = format!("owner={} definition={} origin=generated expansion=derive-default source-projection=false anchor-file={} anchor-start={} anchor-end={} kind={}",
            semantic::quote(&reference.owner), semantic::quote(&owner.generated_from),
            semantic::quote(&reference.file), reference.start, reference.end, reference.kind);
        if reference.target.is_empty() {
            result.add("references", &reference.owner, fact(&reference.owner, "source-claim", "generated-reference",
                &format!("{detail} target=unavailable claim=partial")));
        } else {
            edge(&mut result, "references", &reference.owner, &reference.target, "source-claim", &detail);
            edge(&mut result, "uses", &reference.target, &reference.owner, "source-claim", &detail);
            edge(&mut result, "dependents", &reference.target, &reference.owner, "source-claim",
                &format!("{detail} change=signature conservative=true"));
        }
    }
    for reference in &catalog.unresolved {
        result.add("references", &reference.owner, fact(&reference.owner, "source-claim", "unresolved-reference",
            &format!("file={} start={} end={} kind={} claim=partial",
                semantic::quote(&reference.file), reference.start, reference.end, reference.kind)));
    }
    let program = checked.program();
    let relations = authority::relations(checked);
    let mut effects: Vec<BTreeSet<String>> = Vec::new();
    let mut parents: Vec<Vec<usize>> = vec![Vec::new(); program.functions.len()];
    for (index, relation) in relations.iter().enumerate() {
        let mut names = BTreeSet::new();
        for operation in &relation.operations { names.insert(operation.name.clone()); }
        effects.push(names);
        for (callee, _) in &relation.calls { parents[*callee].push(index); }
    }
    // Effects form a finite set; propagate changed summaries to immediate users.
    // This stores no transitive all-pairs function relation.
    let mut pending: Vec<usize> = Vec::new();
    for index in 0usize..program.functions.len() { pending.push(index); }
    let mut queued = vec![true; program.functions.len()];
    while let Some(index) = pending.pop() {
        queued[index] = false;
        let mut inherited: Vec<String> = Vec::new();
        for effect in &effects[index] { inherited.push(effect.clone()); }
        for parent in &parents[index] {
            let mut changed = false;
            for effect in &inherited { if effects[*parent].insert(effect.clone()) { changed = true; } }
            if changed && !queued[*parent] { queued[*parent] = true; pending.push(*parent); }
        }
    }
    for (index, function) in program.functions.iter().enumerate() {
        let identity = &catalog.instance_ids[index];
        let source = &catalog.instance_sources[index];
        let source_mapping = if source.is_empty() { "unavailable" } else { source.as_str() };
        let native_size = match native_sizes.get(&function.name) {
            Some(bytes) => format!("native-bytes={bytes} native-emitted={} native-size=producer-measurement", *bytes != 0usize),
            None => "native-bytes=unavailable".to_string(),
        };
        let instance = fact(identity, "checked-ir", "instance",
            &format!("source-claim={} arguments={} ir-operations={} {}",
                semantic::quote(source_mapping), semantic::quote(&catalog.instance_arguments[index]), function.body.len(), native_size));

        result.add("instances", identity, instance.clone());
        if !source.is_empty() { result.add("instances", source, instance); }
        result.add("meta", identity, fact(identity, "checked-ir", "function", &format!("source-claim={}", semantic::quote(source_mapping))));
        result.add("type", identity, fact(identity, "checked-ir", "result", &format!("type={}", semantic::quote(&semantic::ir_type_name(program, function.result)))));
        for (local_index, local) in function.locals.iter().enumerate() {
            result.add("type", identity, fact(&format!("{}::local:{}", identity, local_index), "checked-ir", "local",
                &format!("name={} type={} mutable={} parameter={}", semantic::quote(&local.name),
                    semantic::quote(&semantic::ir_type_name(program, local.ty)), local.mutable, local_index < function.params)));
        }
        let summary = fact(identity, "checked-ir", "authority", &format!("reachable-effects={} ownership-cleanup=included", semantic::quote(&join(&effects[index]))));
        result.add("authority", identity, summary.clone());
        if !source.is_empty() { result.add("authority", source, summary); }
        for (callee, cleanup) in &relations[index].calls {
            let target = &catalog.instance_ids[*callee];
            let detail = format!("caller={} cleanup={}", semantic::quote(identity), cleanup);
            edge(&mut result, "callees", identity, target, "checked-ir", &detail);
            edge(&mut result, "callers", target, identity, "checked-ir", &format!("callee={} cleanup={}", semantic::quote(target), cleanup));
            let target_source = &catalog.instance_sources[*callee];
            if !source.is_empty() && !target_source.is_empty() {
                edge(&mut result, "callees", source, target_source, "checked-ir",
                    &format!("caller-instance={} callee-instance={} mapping=source-claim cleanup={}", semantic::quote(identity), semantic::quote(target), cleanup));
                edge(&mut result, "callers", target_source, source, "checked-ir",
                    &format!("caller-instance={} callee-instance={} mapping=source-claim cleanup={}", semantic::quote(identity), semantic::quote(target), cleanup));
                edge(&mut result, "dependents", target_source, source, "source-claim", "change=signature checked-instance-call=true conservative=true");
            }
        }
    }
    let layouts = native::semantic::layouts(checked).map_err(|problem| problem.message)?;
    let type_ids = crate::meaning::verified::type_identities(checked)?;
    for (index, ty) in program.types.iter().enumerate() {
        let name = semantic::ir_type_name(program, index);
        let identity = format!("ir:type:{}", name);
        let layout = &layouts[index];
        let line = fact(&identity, "checked-ir", "layout",
            &format!("target=linux-x86_64 bytes={} alignment={} fields={} cleanup={} representation-id={} representation-domain=lkjscript-ir-type-identity-linux-x86_64-1",
                layout.bytes, layout.alignment, numbers(&layout.fields), layout.cleanup, type_ids[index]));
        result.add("layout", &identity, line.clone());
        result.add("layout", &name, line);
        let type_fact = fact(&identity, "checked-ir", "type", &format!("name={} representation-id={} representation-domain=lkjscript-ir-type-identity-linux-x86_64-1", semantic::quote(&name), type_ids[index]));
        result.add("type", &identity, type_fact.clone());
        result.add("type", &name, type_fact);
        for (variant, offsets) in layout.variants.iter().enumerate() {
            result.add("layout", &identity, fact(&identity, "checked-ir", "variant-layout",
                &format!("variant={variant} fields={}", numbers(offsets))));
        }
        result.add("meta", &identity, fact(&identity, "checked-ir", "type", &format!("name={}", semantic::quote(&name))));
        let base = match name.find('<') { Some(at) => &name[..at], None => &name };
        if base != name.as_str() && catalog.by_identity.contains_key(&base.to_string()) {
            result.add("layout", base, fact(&identity, "checked-ir", "layout",
                &format!("target=linux-x86_64 bytes={} alignment={} source-claim={} representation-id={} representation-domain=lkjscript-ir-type-identity-linux-x86_64-1", layout.bytes, layout.alignment, semantic::quote(base), type_ids[index])));
        }
    }
    let records = std::mem::replace(&mut result.records, BTreeMap::new());
    for (key, mut lines) in records {
        lines.sort();
        let old = std::mem::replace(&mut lines, Vec::new());
        let mut previous: Option<String> = None;
        for line in old {
            let different = match &previous { Some(old) => old != &line, None => true };
            if different {
                previous = Some(line.clone()); lines.push(line);
            }
        }
        result.records.insert(key, lines);
    }
    Ok(result)
}

pub(crate) fn validate_item(target: &semantic::Item, inputs: &[(String, Vec<u8>)], expected: &str) -> Result<(), String> {
    if !target.generated_from.is_empty() {
        return Err(error(&target.identity, "GENERATED_SOURCE",
            &format!("derive-default projection has no editable source; edit defining item {}", semantic::quote(&target.generated_from))));
    }
    let bytes = input(inputs, &target.file)?;
    if target.start > target.end || target.end > bytes.len() {
        return Err(error(&target.identity, "SPAN", "catalog span is outside its input"));
    }
    if sha256::hex_digest(bytes) != target.file_digest
        || bytes[target.start..target.end] != *target.text.as_bytes() {
        return Err(error(&target.identity, "STALE", "catalog and source snapshot disagree"));
    }
    if !expected.is_empty() && expected != target.text_digest {
        return Err(error(&target.identity, "STALE", "expected item digest differs"));
    }
    Ok(())
}

pub fn plan(catalog: &semantic::Catalog,
    inputs: &[(String, Vec<u8>)], request: &Request) -> Result<Draft, String> {
    if !request.snapshot.is_empty() && request.snapshot != catalog.input_digest {
        return Err(error("transaction", "STALE", "expected source snapshot differs"));
    }
    let mut patches = Vec::new();
    let mut projections = Vec::new();
    let mut projected_identities: BTreeSet<String> = BTreeSet::new();
    let mut projected_paths: BTreeSet<String> = BTreeSet::new();
    for operation in &request.operations {
        if let Some(index) = catalog.by_identity.get(&operation.identity) {
            let selected = &catalog.items[*index];
            if !selected.generated_from.is_empty() { validate_item(selected, inputs, &operation.expected)?; }
            if selected.kind == "function" && matches!(operation.kind.as_str(),
                "rename" | "move" | "change-signature" | "inline-function" | "remove-item") {
                for site in &catalog.generated_references {
                    if site.kind == "call" && site.target == selected.identity {
                        let owner = item(catalog, &site.owner)?;
                        return Err(error(&selected.identity, "GENERATED_REFERENCE",
                            &format!("call from {} has no editable source; edit defining item {}",
                                semantic::quote(&site.owner), semantic::quote(&owner.generated_from))));
                    }
                }
            }
        }
        if operation.kind == "add-item" {
            if let Some(projected) = projection(catalog, operation)? {
                if !projected_identities.insert(projected.identity.clone())
                    || !projected_paths.insert(projected.path.clone()) {
                    return Err(error(&projected.identity, "PROJECTION", "duplicate projected identity or path"));
                }
                projections.push(projected);
            } else { one_item(&operation.identity, &operation.source, false)?; }
            let (file, at) = add_location(catalog, inputs, operation)?;
            patch(&mut patches, &operation.identity, &file, at, at, &format!("\n{}\n", operation.source));
            continue;
        }
        let target = item(catalog, &operation.identity)?;
        validate_item(target, inputs, &operation.expected)?;
        if crate::structure_refactor::plan(catalog, inputs, operation, &mut patches)? { continue; }
        match operation.kind.as_str() {
            "replace-body" => {
                let (start, end) = target.body.ok_or_else(|| error(&operation.identity, "BODY", "identity has no source body"))?;
                if operation.source.is_empty() { return Err(error(&operation.identity, "BODY", "replacement body is empty")); }
                one_item(&operation.identity, &operation.source, true)?;
                patch(&mut patches, &operation.identity, &target.file, start, end, &operation.source);
            }
            "replace-item" => {
                if operation.source.is_empty() { return Err(error(&operation.identity, "ITEM", "replacement item is empty")); }
                one_item(&operation.identity, &operation.source, false)?;
                patch(&mut patches, &operation.identity, &target.file, target.start, target.end, &operation.source);
            }
            "remove-item" => {
                let (start, end) = remove_span(target, inputs)?;
                patch(&mut patches, &operation.identity, &target.file, start, end, "");
            },
            "rename" => return Err(error(&operation.identity, "REFERENCES",
                "this identity has no complete source-scope rename proof")),
            "move" => {
                // Relocation within one semantic module preserves the source
                // identity. Cross-module relocation also needs resolved path edits.
                if operation.parent != target.parent {
                    return Err(error(&operation.identity, "REFERENCES", "cross-module move requires complete resolved path rewrites"));
                }
                let (file, at) = insertion(catalog, inputs, &operation.parent)?;
                if file == target.file && target.start <= at && at < target.end {
                    return Err(error(&operation.identity, "OVERLAP", "cannot move an item into itself"));
                }
                let (start, end) = remove_span(target, inputs)?;
                patch(&mut patches, &operation.identity, &target.file, start, end, "");
                patch(&mut patches, &operation.identity, &file, at, at, &format!("\n{}\n", target.text));
            }
            _ => return Err(error(&operation.identity, "OPERATION", &format!("unsupported structural operation {}", operation.kind))),
        }
    }
    let mut draft = finish(inputs, patches)?;
    for projected in &projections { draft.identities.push(projected.identity.clone()); }
    draft.projections = projections;
    Ok(draft)
}

fn items(catalog: &semantic::Catalog) -> Result<Items, String> {
    let mut ordered: BTreeMap<(String, usize, usize, String), usize> = BTreeMap::new();
    for (index, item) in catalog.items.iter().enumerate() {
        if selectable(&item.kind) && item.generated_from.is_empty() {
            ordered.insert((item.file.clone(), item.start, !item.end, item.identity.clone()), index);
        }
    }
    let mut result = Items { by_file: BTreeMap::new(), by_identity: BTreeMap::new() };
    let mut file = String::new(); let mut end = 0usize;
    for (_, index) in ordered {
        let item = &catalog.items[index];
        if item.file == file && item.start < end {
            if item.end <= end { continue; }
            return Err(failure(&item.identity, "OVERLAP", "declaration spans overlap without containment"));
        }
        file = item.file.clone(); end = item.end;
        result.by_identity.insert(item.identity.clone(), index);
        if !result.by_file.contains_key(&file) { result.by_file.insert(file.clone(), Vec::new()); }
        result.by_file.get_mut(&file).unwrap().push(index);
    }
    Ok(result)
}

fn file_pairs_allowed(before: &semantic::Catalog, before_inputs: &[(String, Vec<u8>)],
    after: &semantic::Catalog, after_inputs: &[(String, Vec<u8>)],
    new_files: &BTreeMap<String, bool>) -> Result<BTreeMap<String, String>, String> {
    let mut files = BTreeMap::new(); let mut reverse = BTreeMap::new();
    pair(&mut files, &mut reverse, &before.root, &after.root)?;
    for item in &before.items {
        if !selectable(&item.kind) || !item.generated_from.is_empty() { continue; }
        if let Some(index) = after.by_identity.get(&item.identity) {
            if !after.items[*index].generated_from.is_empty() { continue; }
            pair(&mut files, &mut reverse, &item.file, &after.items[*index].file)?;
        }
    }
    for old_source in &before.module_sources {
        if let Some(new_source) = mounted(after, &old_source.identity) {
            pair(&mut files, &mut reverse, &old_source.file, &new_source.file)?;
        }
    }
    // Infer directory correspondence only from the root and stable source
    // identities. Include-only inputs have no item identity of their own.
    let mut directories: BTreeMap<String, Vec<String>> = BTreeMap::new();
    for (old_file, new_file) in &files {
        let old_directory = directory(old_file);
        let new_directory = directory(new_file);
        if !directories.contains_key(&old_directory) {
            directories.insert(old_directory.clone(), Vec::new());
        }
        let targets = directories.get_mut(&old_directory).unwrap();
        if !targets.contains(&new_directory) { targets.push(new_directory); }
    }
    let after_index = input_index(after_inputs)?;
    for (path, _) in before_inputs {
        if files.contains_key(path) { continue; }
        if after_index.contains_key(path) {
            pair(&mut files, &mut reverse, path, path)?;
            continue;
        }
        let mut selected = false;
        let mut prefix_length = 0usize;
        let mut target_directory = String::new();
        let mut ambiguous = false;
        for (old_directory, targets) in &directories {
            if path.starts_with(old_directory) && (!selected || old_directory.len() > prefix_length) {
                selected = true;
                prefix_length = old_directory.len();
                ambiguous = targets.len() != 1usize;
                target_directory = if ambiguous { String::new() } else { targets[0].clone() };
            }
        }
        if selected {
            if ambiguous {
                return Err(failure(path, "FILE_AMBIGUOUS", "stable identities imply several counterpart directories for this include-only input"));
            }
            let candidate = format!("{}{}", target_directory, &path[prefix_length..]);
            if after_index.contains_key(&candidate) {
                pair(&mut files, &mut reverse, path, &candidate)?;
                continue;
            }
        }
        return Err(failure(path, "FILES", "source file has no stable identity or unambiguous relative-path counterpart"));
    }
    for (path, _) in after_inputs {
        if !reverse.contains_key(path) && !new_files.contains_key(path) {
            return Err(failure(path, "FILES", "a newly loaded file needs an explicit file-creation operation"));
        }
    }
    for (path, _) in new_files {
        if reverse.contains_key(path) {
            return Err(failure(path, "MODULE_EXISTING", "a projected module body already has an existing input counterpart"));
        }
    }
    Ok(files)
}
